289. 
290. Writes the tier-relevant slice of the metrics glossary next to `report.html`.
291. Plain static class (no `[TestClass]`) — MSTest allows only one
292. `[AssemblyCleanup]`, so this is chained from `AievalReport` (next file).
293. 
294. ```csharp
295. namespace {{AppName}}.Evals.Tests;
296. 
297. internal static class MetricsGlossary
298. {
299.     public static void WriteGlossary()
300.     {
301.         var outDir = Path.Combine(
302.             RepoRoot.Find(), ".copilot", "perf-reports", "evals", EvalEnv.ReportFolder);
303.         Directory.CreateDirectory(outDir);
304.         var path = Path.Combine(outDir, "metrics-glossary.md");
305. 
306.         var sb = new StringBuilder();
307.         sb.AppendLine($"# Metrics glossary — {EvalEnv.Tier} tier");
308.         sb.AppendLine();
309.         sb.AppendLine($"Generated: {DateTime.UtcNow:O}");
310.         sb.AppendLine();
311.         sb.AppendLine("Companion to `report.html` in this folder. The aieval HTML report shows numbers; this file explains them.");
312.         sb.AppendLine();
313. 
314.         sb.AppendLine(NlpEntries);
315.         if (EvalEnv.UseRealJudge) sb.AppendLine(QualityEntries);
316.         if (EvalEnv.UseFoundrySafety) sb.AppendLine(SafetyEntries);
317. 
318.         sb.AppendLine();
319.         sb.AppendLine("> Source: setup-maf-evals references/metrics-glossary.md");
320. 
321.         File.WriteAllText(path, sb.ToString());
322.         Console.WriteLine($"[MetricsGlossary] {path}");
323.     }
324. 
