        var text = $"(stub IChatClient) Echoing: {last}";
        var response = new ChatResponse(new ChatMessage(ChatRole.Assistant, text))
        {
            ModelId = "stub",
            Usage = new UsageDetails { InputTokenCount = 0, OutputTokenCount = 0 },
        };
        return Task.FromResult(response);
    }

